css:
[data-thread-item]{border-radius:6px!important;}
[data-slot="composer-host"]{border-radius:10px!important;box-shadow:none!important;border:1px solid var(--border)!important;}
[data-user-message-bubble]{border-radius:8px!important;}
.chat-markdown-codeblock{border-radius:6px!important;border:1px solid var(--border);}
[data-slot="button"]{border-radius:6px!important;}
[data-slot="input"],[data-slot="select-trigger"]{border-radius:6px!important;}
[data-slot="dialog-popup"],[data-slot="popover-popup"],[data-slot="menu-popup"]{border-radius:8px!important;border:1px solid var(--border)!important;box-shadow:0 0 1rem rgba(0,0,0,.02),0 0 .5rem rgba(0,0,0,.01)!important;}
[data-slot="tooltip-popup"]{border-radius:5px!important;}
svg.lucide{stroke-width:1.75;}
[data-slot="scroll-area-thumb"]{border-radius:999px;}
::-webkit-scrollbar{width:10px;height:10px;}
::-webkit-scrollbar-thumb{background:color-mix(in srgb,var(--foreground) 12%,transparent);border-radius:999px;border:2px solid transparent;background-clip:padding-box;}
::-webkit-scrollbar-thumb:hover{background-color:color-mix(in srgb,var(--foreground) 20%,transparent);}
::selection{background:color-mix(in srgb,var(--foreground) 15%,transparent);}
[data-slot="sidebar"]{border-right:1px solid var(--border)!important;}
button.bg-message-action:disabled{background:color-mix(in srgb,var(--foreground) 12%,transparent)!important;color:var(--muted-foreground)!important;opacity:1!important;}
.dark [data-slot="switch"][data-unchecked]{background:#2B2923!important;box-shadow:none!important;}
.dark [data-slot="switch"][data-unchecked] [data-slot="switch-thumb"]{background:#969592!important;}
.dark [data-slot="switch"][data-checked]{background:#F54E00!important;box-shadow:none!important;}
.dark [data-slot="switch"][data-checked] [data-slot="switch-thumb"]{background:#FFFFFF!important;}
:root:not(.dark) [data-slot="switch"][data-unchecked]{background:#CDCDC9!important;}
:root:not(.dark) [data-slot="switch"][data-unchecked] [data-slot="switch-thumb"]{background:#FFFFFF!important;}
:root:not(.dark) [data-slot="switch"][data-checked]{background:#F54E00!important;}
:root:not(.dark) [data-slot="switch"][data-checked] [data-slot="switch-thumb"]{background:#FFFFFF!important;}
